const settingText = (value, fallback = '') => {
  const text = String(value ?? '').trim();
  return text || fallback;
};
const settingInt = (value, fallback) => {
  const parsed = Number.parseInt(String(value ?? ''), 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};

const botSettings = $json ?? {};
const update = $('Telegram Trigger').first().json;
const callback = update.callback_query ?? null;
const message = update.message ?? callback?.message ?? {};
const from = update.message?.from ?? callback?.from ?? {};
const chat = message.chat ?? {};
const rawMessageText = typeof update.message?.text === 'string' ? update.message.text : '';
const callbackData = typeof callback?.data === 'string' ? callback.data : '';
const accessPasswordConfigured = Boolean(botSettings.access_password_configured);
const accessPasswordMatched = Boolean(botSettings.access_password_matched);
const messageText = accessPasswordMatched ? '[access-password]' : '';
const trimmedText = '';
const command = '';

const numberOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

return [
  {
    json: {
      updateType: callback ? 'callback_query' : 'message',
      telegramUserId: numberOrNull(from.id),
      chatId: numberOrNull(chat.id),
      messageId: numberOrNull(message.message_id),
      callbackQueryId: callback?.id ?? '',
      callbackData,
      messageText,
      trimmedText,
      command,
      isTextMessage: Boolean(update.message && typeof update.message.text === 'string'),
      isCallback: Boolean(callback),
      username: from.username ?? '',
      firstName: from.first_name ?? '',
      lastName: from.last_name ?? '',
      accessPasswordConfigured,
      accessPasswordMatched,
      settings: {
        telegramBotApiBaseUrl: settingText(botSettings.telegram_bot_api_base_url).replace(/\/$/, ''),
        maxAgentsPerUser: settingInt(botSettings.max_agents_per_user, 3),
        defaultPrompt: settingText(botSettings.default_agent_prompt, 'You are a helpful voice assistant.'),
        defaultWelcome: settingText(botSettings.default_agent_welcome, 'Hello, how can I help you today?'),
        defaultLanguage: settingText(botSettings.default_agent_language, 'en'),
        defaultVoiceId: settingText(botSettings.default_agent_voice_id, 'cjVigY5qzO86Huf0OWal'),
        defaultTtsModelId: settingText(botSettings.default_agent_tts_model_id, 'eleven_turbo_v2'),
        defaultLlm: settingText(botSettings.default_agent_llm, 'gpt-4o-mini'),
      },
    },
  },
];

const normalized = $('Restore Normalized Telegram Update').first().json;
const user = typeof $json.user_record === 'string' ? JSON.parse($json.user_record) : $json.user_record;
const triggerUpdate = $('Telegram Trigger').first().json;
const rawMessageText = user && typeof triggerUpdate.message?.text === 'string' ? triggerUpdate.message.text : '';
const trimmedText = rawMessageText.trim();
const messageText = user ? rawMessageText : normalized.messageText;
const command = user ? (trimmedText.split(/\s+/)[0] || '') : normalized.command;

return [{ json: { ...normalized, ...$json, messageText, trimmedText: user ? trimmedText : normalized.trimmedText, command } }];

const user = typeof $json.user_record === 'string' ? JSON.parse($json.user_record) : $json.user_record;
const agents = typeof $json.agents === 'string' ? JSON.parse($json.agents) : ($json.agents ?? []);
const activeAgent = typeof $json.active_agent === 'string' ? JSON.parse($json.active_agent) : $json.active_agent;
const settings = $json.settings ?? {};
const maxAgents = Number.isFinite(settings.maxAgentsPerUser) ? settings.maxAgentsPerUser : 3;

const button = (text, data) => ({ text, callback_data: data });
const agentsKeyboard = () => {
  const rows = agents.map((agent) => [button(agent.is_active ? `✓ ${agent.display_name}` : agent.display_name, `ag:sel:${agent.id}`)]);
  if (agents.length < maxAgents) rows.push([button('Создать агента', 'ag:new')]);
  return { inline_keyboard: rows };
};
const actionsKeyboard = () => ({
  inline_keyboard: [
    [button('Изменить prompt', 'ag:p')],
    [button('Изменить приветствие', 'ag:w')],
    [button('Обновить knowledge', 'ag:k')],
    [button('Список агентов', 'ag:list')],
  ],
});
const menuText = () => [
  'Доступ открыт.',
  `Лимит агентов: ${maxAgents}.`,
  'Команда /agents покажет список агентов и действия.',
].join('\n');
const reply = (route, text, extra = {}) => [{ json: { ...$json, route, replyText: text, replyMarkup: extra.replyMarkup ?? null, ...extra } }];
const callbackExtra = (extra = {}) => ($json.isCallback ? { ...extra, answerCallback: true } : extra);

if (!$json.telegramUserId || !$json.chatId) {
  return reply('reply', 'Не вижу Telegram user id или chat id. Попробуйте отправить сообщение еще раз.', callbackExtra());
}

if (!user) {
  if (!$json.accessPasswordConfigured) {
    return reply('reply', 'Доступ временно не настроен. Попробуйте позже.', callbackExtra());
  }
  if ($json.isTextMessage && $json.accessPasswordMatched) {
    return reply('register_user', menuText());
  }
  return reply('reply', 'Пришлите пароль доступа текстовым сообщением.', callbackExtra());
}

if ($json.isCallback && $json.callbackData) {
  if ($json.callbackData === 'ag:list') {
    return reply('reply', agents.length ? 'Ваши агенты:' : 'У вас пока нет агентов.', { replyMarkup: agentsKeyboard(), answerCallback: true });
  }
  if ($json.callbackData === 'ag:new') {
    if (agents.length >= maxAgents) {
      return reply('reply', `Лимит агентов исчерпан: ${maxAgents}.`, { answerCallback: true });
    }
    return reply('set_state', 'Как назвать нового агента? Пришлите имя текстом.', { nextState: 'awaiting_agent_name', answerCallback: true });
  }
  if ($json.callbackData.startsWith('ag:sel:')) {
    const localAgentId = Number.parseInt($json.callbackData.slice('ag:sel:'.length), 10);
    const selected = agents.find((agent) => agent.id === localAgentId);
    if (!selected) return reply('reply', 'Этот агент вам не принадлежит. Выберите агента через /agents.', { answerCallback: true });
    return reply('set_active_agent', `Выбран агент: ${selected.display_name}`, { activeAgentId: localAgentId, nextState: 'idle', replyMarkup: actionsKeyboard(), answerCallback: true });
  }
  if (['ag:p', 'ag:w', 'ag:k'].includes($json.callbackData)) {
    if (!activeAgent?.id) return reply('reply', 'Сначала выберите агента через /agents.', { answerCallback: true });
    const states = { 'ag:p': 'awaiting_prompt', 'ag:w': 'awaiting_welcome', 'ag:k': 'awaiting_knowledge' };
    const texts = {
      'ag:p': 'Пришлите новый prompt текстом.',
      'ag:w': 'Пришлите новое приветствие текстом.',
      'ag:k': 'Пришлите новый knowledge content текстом.',
    };
    return reply('set_state', texts[$json.callbackData], { nextState: states[$json.callbackData], answerCallback: true });
  }
  return reply('reply', 'Неизвестное действие. Откройте /agents.', { answerCallback: true });
}

if ($json.command === '/start') return reply('reset_to_menu', menuText(), { nextState: 'idle' });
if ($json.command === '/agents') return reply('reply', agents.length ? 'Ваши агенты:' : 'У вас пока нет агентов.', { replyMarkup: agentsKeyboard() });

if (user.dialog_state === 'awaiting_agent_name') {
  if (!$json.isTextMessage || !$json.trimmedText) return reply('reply', 'Имя агента нужно отправить текстом.');
  if (agents.length >= maxAgents) return reply('reset_to_menu', `Лимит агентов исчерпан: ${maxAgents}.`, { nextState: 'idle' });
  return reply('create_agent', 'Создаю агента...', { agentName: $json.trimmedText });
}

if (['awaiting_prompt', 'awaiting_welcome', 'awaiting_knowledge'].includes(user.dialog_state)) {
  if (!activeAgent?.id) return reply('reset_to_menu', 'Сначала выберите агента через /agents.', { nextState: 'idle' });
  if (!$json.isTextMessage || !$json.trimmedText) return reply('reply', 'Пришлите текст. Файлы, голосовые и прочая роскошь в этой версии не принимаются.');
  const routeByState = {
    awaiting_prompt: 'update_prompt',
    awaiting_welcome: 'update_welcome',
    awaiting_knowledge: 'update_knowledge',
  };
  return reply(routeByState[user.dialog_state], 'Обновляю агента...', { newText: $json.trimmedText });
}

return reply('reply', 'Откройте /agents, чтобы выбрать или создать агента.');

if ($json.answerCallback && $json.callbackQueryId) {
  return [{ json: $json }];
}
return [];

const route = $('Route Telegram Event').first().json;
if ($json.replyText) {
  return [{ json: { ...route, ...$json, stateResult: $json } }];
}
return [{ json: { ...$json, ...route, stateResult: $json } }];

if ($json.replyMarkup) {
  return [];
}
return [{ json: $json }];

if (!$json.replyMarkup) {
  return [];
}

const telegramRequestBody = {
  chat_id: $json.chatId,
  text: $json.replyText,
  reply_markup: $json.replyMarkup,
};

if ($json.messageId) {
  telegramRequestBody.reply_to_message_id = $json.messageId;
}

return [{ json: { ...$json, telegramRequestBody } }];

const pendingText = [
  'Действие принято, но узлы ElevenLabs еще не подключены в этом экспортированном workflow.',
  'Продолжу настройку следующим шагом.',
].join('\n');

return [{ json: { ...$json, replyText: pendingText, replyMarkup: null } }];

const settings = $json.settings ?? {};
const agents = typeof $json.agents === 'string' ? JSON.parse($json.agents) : ($json.agents ?? []);
const maxAgents = Number.isFinite(settings.maxAgentsPerUser) ? settings.maxAgentsPerUser : 3;
const agentName = String($json.agentName ?? '').trim().slice(0, 80);

if (!$json.user_record || !agentName) {
  throw new Error('Cannot create ElevenLabs agent without a registered user and agent name.');
}

if (agents.length >= maxAgents) {
  throw new Error(`Agent limit exceeded before create request: ${maxAgents}.`);
}

const defaultPrompt = settings.defaultPrompt ?? 'You are a helpful voice assistant.';
const defaultWelcome = settings.defaultWelcome ?? 'Hello, how can I help you today?';
const defaultLanguage = settings.defaultLanguage ?? 'en';
const defaultVoiceId = settings.defaultVoiceId ?? 'cjVigY5qzO86Huf0OWal';
const defaultTtsModelId = settings.defaultTtsModelId ?? 'eleven_turbo_v2';
const defaultLlm = settings.defaultLlm ?? 'gemini-2.5-flash';
const reservationKey = `pending:${$json.telegramUserId}:${Date.now()}:${Math.random().toString(36).slice(2)}`;

const elevenLabsCreateAgentBody = {
  name: agentName,
  tags: ['telegram-bot', 'n8n-managed'],
  conversation_config: {
    agent: {
      first_message: defaultWelcome,
      language: defaultLanguage,
      prompt: {
        prompt: defaultPrompt,
        llm: defaultLlm,
      },
    },
    tts: {
      voice_id: defaultVoiceId,
      model_id: defaultTtsModelId,
    },
  },
};

return [{ json: { ...$json, agentName, defaultPrompt, defaultWelcome, reservationKey, elevenLabsCreateAgentBody } }];

const route = $('Prepare Reserved Agent Create').first().json;
const saved = $('Save Created Agent').first().json;
const agents = typeof $json.agents === 'string' ? JSON.parse($json.agents) : ($json.agents ?? []);
if (!saved?.id) {
  throw new Error('Created ElevenLabs agent was not saved locally, most likely because the user agent limit was reached concurrently.');
}

const createdAgentName = saved.display_name ?? route.agentName;
const activeLocalId = Number(saved.id);

const button = (text, data) => ({ text, callback_data: data });
const actionsKeyboard = () => ({
  inline_keyboard: [
    [button('Изменить prompt', 'ag:p')],
    [button('Изменить приветствие', 'ag:w')],
    [button('Обновить knowledge', 'ag:k')],
    [button('Список агентов', 'ag:list')],
  ],
});

return [{
  json: {
    ...route,
    ...$json,
    agents,
    activeAgentId: activeLocalId,
    replyText: `Агент создан: ${createdAgentName}.`,
    replyMarkup: actionsKeyboard(),
  },
}];

const payload = $('Build ElevenLabs Agent Payload').first().json;
const reserved = typeof $json.reserved_agent === 'string' ? JSON.parse($json.reserved_agent) : $json.reserved_agent;

if (reserved?.id) {
  return [];
}

return [{
  json: {
    ...payload,
    ...$json,
    replyText: `Лимит агентов исчерпан: ${$json.max_agents ?? payload.settings?.maxAgentsPerUser ?? 3}.`,
    replyMarkup: null,
    nextState: 'idle',
  },
}];

const payload = $('Build ElevenLabs Agent Payload').first().json;
const reserved = typeof $json.reserved_agent === 'string' ? JSON.parse($json.reserved_agent) : $json.reserved_agent;

if (!reserved?.id) {
  return [];
}

return [{
  json: {
    ...payload,
    reservationLocalAgentId: reserved.id,
    reservationKey: reserved.elevenlabs_agent_id,
  },
}];

const route = $('Restore Validated Agent Update Context').first().json;
const activeAgent = route.activeAgent;
const fetchedAgent = $('Get ElevenLabs Agent').first().json;
const currentConfig = structuredClone(fetchedAgent.conversation_config ?? {});
currentConfig.agent = currentConfig.agent ?? {};
currentConfig.agent.prompt = currentConfig.agent.prompt ?? {};

const routeToKind = {
  update_prompt: 'prompt',
  update_welcome: 'welcome',
  update_knowledge: 'knowledge',
};
const updateKind = routeToKind[route.route];
const newText = String(route.newText ?? '').trim();

if (!updateKind) {
  throw new Error(`Unsupported ElevenLabs patch route: ${route.route}`);
}

if (!activeAgent?.id || !activeAgent.elevenlabs_agent_id) {
  throw new Error('Cannot update ElevenLabs agent without an active user-owned agent.');
}

if (!newText) {
  throw new Error('Cannot update ElevenLabs agent with empty text.');
}

let newKnowledgeDocumentId = '';
let newKnowledgeDocumentName = '';
let previousKnowledgeDocumentId = activeAgent.knowledge_document_id ?? '';

if (updateKind === 'prompt') {
  currentConfig.agent.prompt = {
    ...(currentConfig.agent.prompt ?? {}),
    prompt: newText,
  };
} else if (updateKind === 'welcome') {
  currentConfig.agent.first_message = newText;
} else {
  const document = $('Create Knowledge Document').first().json;
  if (!document?.id) {
    throw new Error('ElevenLabs knowledge document was not created.');
  }

  newKnowledgeDocumentId = document.id;
  newKnowledgeDocumentName = document.name ?? 'Telegram knowledge';

  const existingKnowledge = currentConfig.agent.prompt.knowledge_base ?? currentConfig.agent.prompt.knowledgeBase ?? [];
  const preservedKnowledge = Array.isArray(existingKnowledge)
    ? existingKnowledge.filter((entry) => entry?.id && entry.id !== previousKnowledgeDocumentId)
    : [];

  currentConfig.agent.prompt.knowledge_base = [
    ...preservedKnowledge,
    {
      type: 'text',
      name: newKnowledgeDocumentName,
      id: newKnowledgeDocumentId,
      usage_mode: 'prompt',
    },
  ];
  delete currentConfig.agent.prompt.knowledgeBase;
}

const elevenLabsPatchBody = {
  conversation_config: currentConfig,
};

return [{
  json: {
    ...route,
    activeAgent,
    updateKind,
    newText,
    previousKnowledgeDocumentId,
    newKnowledgeDocumentId,
    newKnowledgeDocumentName,
    elevenLabsPatchBody,
  },
}];

const route = $('Build ElevenLabs Patch').first().json;
const saved = $('Save Agent Update').first().json;

if (!saved?.id) {
  throw new Error('Updated ElevenLabs agent was not saved locally for the current Telegram user.');
}

const button = (text, data) => ({ text, callback_data: data });
const actionsKeyboard = () => ({
  inline_keyboard: [
    [button('Изменить prompt', 'ag:p')],
    [button('Изменить приветствие', 'ag:w')],
    [button('Обновить knowledge', 'ag:k')],
    [button('Список агентов', 'ag:list')],
  ],
});

const labels = { prompt: 'Prompt', welcome: 'Приветствие', knowledge: 'Knowledge' };
const label = labels[route.updateKind] ?? 'Агент';

return [{
  json: {
    ...route,
    savedAgent: saved,
    replyText: `${label} обновлен.`,
    replyMarkup: actionsKeyboard(),
  },
}];

const route = $('Route Telegram Event').first().json;
const lockedAgent = typeof $json.validated_agent === 'string' ? JSON.parse($json.validated_agent) : $json.validated_agent;

if (!lockedAgent?.id || !lockedAgent.elevenlabs_agent_id) {
  return [];
}

return [{
  json: {
    ...route,
    activeAgent: {
      id: lockedAgent.id,
      elevenlabs_agent_id: lockedAgent.elevenlabs_agent_id,
      display_name: lockedAgent.display_name,
      knowledge_document_id: lockedAgent.knowledge_document_id,
      prompt_text: lockedAgent.prompt_text,
      welcome_text: lockedAgent.welcome_text,
      status: lockedAgent.status,
    },
  },
}];

const route = $('Route Telegram Event').first().json;
const validatedAgent = typeof $json.validated_agent === 'string' ? JSON.parse($json.validated_agent) : $json.validated_agent;

if (validatedAgent?.id) {
  return [];
}

return [{
  json: {
    ...route,
    replyText: 'Не нашел выбранного агента среди ваших активных агентов. Откройте /agents и выберите агента заново.',
    replyMarkup: null,
    nextState: 'idle',
  },
}];

const route = $('Restore Validated Agent Update Context').first().json;
if (['update_prompt', 'update_welcome'].includes(route.route)) {
  return [{ json: { ...route, currentAgentConfig: $json } }];
}
return [];

const route = $('Restore Validated Agent Update Context').first().json;
if (route.route !== 'update_knowledge') {
  return [];
}

const activeAgent = route.activeAgent;
const text = String(route.newText ?? '').trim();
if (!text) {
  throw new Error('Cannot create an empty ElevenLabs knowledge document.');
}

const safeAgentName = String(activeAgent.display_name ?? 'agent').slice(0, 60);
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const knowledgeDocumentBody = {
  text,
  name: `${safeAgentName} knowledge ${timestamp}`,
};

return [{ json: { ...route, knowledgeDocumentBody } }];

const route = $('Build ElevenLabs Patch').first().json;
if (route.updateKind !== 'knowledge' || !route.previousKnowledgeDocumentId || route.previousKnowledgeDocumentId === route.newKnowledgeDocumentId) {
  return [];
}

return [{
  json: {
    ...route,
    oldKnowledgeDocumentId: route.previousKnowledgeDocumentId,
  },
}];

const source = $json;
const parseMaybe = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
};
const userRecord = parseMaybe(source.user_record);
const activeAgent = parseMaybe(source.active_agent);
const savedAgent = source.savedAgent ?? null;
const route = source.route ?? '';
let eventType = 'bot_reply';
let agentId = source.activeAgent?.id ?? savedAgent?.id ?? source.activeAgentId ?? activeAgent?.id ?? null;

if (route === 'register_user') {
  eventType = 'user_registered';
} else if (route === 'create_agent') {
  eventType = 'agent_created';
} else if (['update_prompt', 'update_welcome', 'update_knowledge'].includes(route)) {
  eventType = route.replace('update_', 'agent_') + '_updated';
}

return [{
  json: {
    ...source,
    botEvent: {
      userId: userRecord?.id ?? source.id ?? null,
      agentId,
      eventType,
      status: 'success',
      errorMessage: '',
      metadata: {
        route,
        updateKind: source.updateKind ?? '',
        telegramUserId: source.telegramUserId ?? source.telegram_user_id ?? null,
        hasReplyMarkup: Boolean(source.replyMarkup),
      },
    },
  },
}];

const cleanup = $('Prepare Old Knowledge Deletion').first().json;
const parseMaybe = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
};
const userRecord = parseMaybe(cleanup.user_record);
const statusCode = Number($json.statusCode ?? ($json.error ? 500 : 200));

if (statusCode < 400 && !$json.error) {
  return [];
}

const message = $json.error
  ? ($json.error.message ?? $json.error.description ?? 'Cleanup request failed')
  : (typeof $json.body === 'string' ? $json.body : ($json.statusMessage ?? 'Cleanup request failed'));

return [{
  json: {
    ...cleanup,
    botEvent: {
      userId: userRecord?.id ?? null,
      agentId: cleanup.activeAgent?.id ?? null,
      eventType: 'delete_old_knowledge_document_failed',
      status: 'error',
      errorMessage: String(message ?? 'Unknown cleanup error').slice(0, 1000),
      metadata: {
        oldKnowledgeDocumentId: cleanup.oldKnowledgeDocumentId,
        newKnowledgeDocumentId: cleanup.newKnowledgeDocumentId,
        statusCode,
      },
    },
  },
}];

const source = $('Prepare Reserved Agent Create').first().json;
if (!$json.error) {
  return [];
}

const parseMaybe = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
};
const userRecord = parseMaybe(source.user_record);
const activeAgent = source.activeAgent ?? parseMaybe(source.active_agent);
const message = typeof $json.error === 'string'
  ? $json.error
  : ($json.error?.message ?? $json.error?.description ?? 'Operation failed');

return [{
  json: {
    ...source,
    replyText: 'Не получилось выполнить действие. Попробуйте позже.',
    replyMarkup: null,
    nextState: 'idle',
    botEvent: {
      userId: userRecord?.id ?? source.id ?? null,
      agentId: activeAgent?.id ?? source.activeAgentId ?? null,
      eventType: 'create_agent_failed',
      status: 'error',
      errorMessage: String(message ?? 'Unknown error').slice(0, 1000),
      metadata: {
        route: source.route ?? '',
        updateKind: source.updateKind ?? '',
        failedNode: 'Create ElevenLabs Agent',
        missingExpectedRow: false,
      },
    },
  },
}];

const source = $('Prepare Reserved Agent Create').first().json;
if (!$json.error && $json.id && $json.telegramUserId) {
  return [];
}

const parseMaybe = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
};
const userRecord = parseMaybe(source.user_record);
const activeAgent = source.activeAgent ?? parseMaybe(source.active_agent);
const message = $json.error
  ? (typeof $json.error === 'string' ? $json.error : ($json.error?.message ?? $json.error?.description ?? 'Operation failed'))
  : 'Operation did not return the expected saved row.';

return [{
  json: {
    ...source,
    replyText: 'Не получилось выполнить действие. Попробуйте позже.',
    replyMarkup: null,
    nextState: 'idle',
    botEvent: {
      userId: userRecord?.id ?? source.id ?? null,
      agentId: activeAgent?.id ?? source.activeAgentId ?? null,
      eventType: 'save_created_agent_failed',
      status: 'error',
      errorMessage: String(message ?? 'Unknown error').slice(0, 1000),
      metadata: {
        route: source.route ?? '',
        updateKind: source.updateKind ?? '',
        failedNode: 'Save Created Agent',
        missingExpectedRow: !$json.error,
      },
    },
  },
}];

const source = $('Build Knowledge Document Request').first().json;
if (!$json.error) {
  return [];
}

const parseMaybe = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
};
const userRecord = parseMaybe(source.user_record);
const activeAgent = source.activeAgent ?? parseMaybe(source.active_agent);
const message = typeof $json.error === 'string'
  ? $json.error
  : ($json.error?.message ?? $json.error?.description ?? 'Operation failed');

return [{
  json: {
    ...source,
    replyText: 'Не получилось выполнить действие. Попробуйте позже.',
    replyMarkup: null,
    nextState: 'idle',
    botEvent: {
      userId: userRecord?.id ?? source.id ?? null,
      agentId: activeAgent?.id ?? source.activeAgentId ?? null,
      eventType: 'create_knowledge_document_failed',
      status: 'error',
      errorMessage: String(message ?? 'Unknown error').slice(0, 1000),
      metadata: {
        route: source.route ?? '',
        updateKind: source.updateKind ?? '',
